import{_ as a,o as t,c as r,S as o}from"./chunks/framework.D1Ss-Xl7.js";const l="/assets/model.png",i="/assets/hotel1_1.png",s="/assets/hotel1_2.png",f=JSON.parse('{"title":"使用最小费用最大流模型解决酒店管理收益最大化问题","description":"","frontmatter":{"title":"使用最小费用最大流模型解决酒店管理收益最大化问题","date":"2015-12-29 11:15","comments":true,"archives":2015,"tags":["algorithm"]},"headers":[],"relativePath":"posts/2015-12-29-minimum-cost-flow-problem/index.md","filePath":"posts/2015/2015-12-29-Minimum-cost-flow-problem.md"}'),n={name:"posts/2015-12-29-minimum-cost-flow-problem/index.md"};function h(m,e,p,d,c,_){return t(),r("div",null,[...e[0]||(e[0]=[o('<p>最近老师布置个作业,很没有头绪,于是各种咨询,大家的解决方案是使用最小费用最大流模型来求解,于是我便花了 3 天时间来理解这个算法.</p><h2 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h2><p>问题很简单,你有一个只有 5 个房间的酒店,然后本周会有 18 个订单到来,怎样接受订单可以使本周的收益达到最大值.也就是把这 18 个订单填写到一个 5*7 的表格里 怎么填收益最大,订单要么接受要么拒绝,也可以说是典型的 01 背包问题吧,但用动态规划不好抽象出来状态转移方程,所以我还是选择用最大流来做.每个订单包含 3 个信息:每晚付的房费,从周几开始入住,入住几天.</p><h2 id="抽象数据模型" tabindex="-1">抽象数据模型 <a class="header-anchor" href="#抽象数据模型" aria-label="Permalink to &quot;抽象数据模型&quot;">​</a></h2><p>因为题目要求是球最大收益,而流模型是最小费用,所以我们把收益取相反数即可.关键是建立容量和权值,因为房间的数量是 5,所以限制源点和汇点的容量是 5,权值是 0.然后中间设置 8 个点,产生 7 条边,每条边代表每天的流,权值为 0,容量为无穷大.这里我们不能简单的连接点来设置订单的边,因为有相同的起始日期和结束日期的订单.这样会造成冲突,如何解决冲突呢? 我们可以在订单的边上再加一个顶点来进行区分.模型图如下所示: <img src="'+l+'" alt="model"> 顶点 11 和顶点 16 是重复边的订单,对应的是第一个订单和第 6 个订单.源码和输入数据可以在文章末尾看到.</p><h2 id="查找增广路径" tabindex="-1">查找增广路径 <a class="header-anchor" href="#查找增广路径" aria-label="Permalink to &quot;查找增广路径&quot;">​</a></h2><p>这里我们使用<a href="https://en.wikipedia.org/wiki/Ford%E2%80%93Fulkerson_algorithm" target="_blank" rel="noreferrer">Ford–Fulkerson</a>算法来计算每次的增广路径.</p><h2 id="路径的查找" tabindex="-1">路径的查找 <a class="header-anchor" href="#路径的查找" aria-label="Permalink to &quot;路径的查找&quot;">​</a></h2><p>每次增广路径的查找都需要得到最小权值的路径.查找路径使用的是<a href="https://en.wikipedia.org/wiki/Shortest_Path_Faster_Algorithm" target="_blank" rel="noreferrer">SPFA</a>算法.</p><h2 id="第一次查找增广路径" tabindex="-1">第一次查找增广路径 <a class="header-anchor" href="#第一次查找增广路径" aria-label="Permalink to &quot;第一次查找增广路径&quot;">​</a></h2><p><img src="'+i+'" alt="hotel1_1"></p><h2 id="第二次查找增广路径" tabindex="-1">第二次查找增广路径 <a class="header-anchor" href="#第二次查找增广路径" aria-label="Permalink to &quot;第二次查找增广路径&quot;">​</a></h2><p><img src="'+s+'" alt="hotel1_2"></p><p>以此类推求出最后的结果~</p><h2 id="参考" tabindex="-1">参考: <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考:&quot;">​</a></h2><p><a href="https://github.com/acgotaku/USTC-Coding/tree/master/hotel" target="_blank" rel="noreferrer">Source code</a></p><p><a href="http://www.cnblogs.com/gaochundong/p/ford_fulkerson_maximum_flow_algorithm.html" target="_blank" rel="noreferrer">Ford–Fulkerson</a></p>',17)])])}const b=a(n,[["render",h]]);export{f as __pageData,b as default};
